-- 112 Haunted Manor: a ghost that came in with its room's scene. It drifts
-- and bobs, fades in and out, and backs away from the walker's torch - and
-- the light it carries is subtractive (`subtract` on its point light), so
-- where it floats the room goes darker. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local ghosts = {}
local walker = nil

function init(entity)
    local x, y = Transform.get_position(entity)
    ghosts[entity] = { x = x, y = y, hx = x, t = (x or 0) * 0.01 }
end

function update(entity, dt)
    local g = ghosts[entity]
    if not g then return end
    g.t = g.t + dt
    if not walker then walker = Entity.find_by_name("Walker") end
    local wx = walker and Transform.get_position(walker) or -1e9
    local away = 0
    if math.abs(wx - g.x) < 260 then away = (g.x > wx) and 1 or -1 end
    g.x = g.x + (g.hx + math.sin(g.t * 0.4) * 160 - g.x) * math.min(1, dt * 0.8) + away * 90 * dt
    g.hx = g.hx + away * 40 * dt
    local y = g.y + math.sin(g.t * 1.3) * 18
    Transform.set_position(entity, g.x, y)
    local a = 0.35 + 0.25 * math.sin(g.t * 0.7)
    Sprite.set_color(entity, 0.85, 0.95, 1.1, a)
    Lighting.set_intensity(entity, 0.6 + a)
end
